const T=[];

T.push({
 id:'buss',lang:'sv',version:1,level:1,genre:'Berättelse',
 title:'Bussen 07.42',
 lead:'Elias har suttit på samma plats i två år. En tisdag sitter någon annan där.',
 purpose:'Läs för att förstå hur Elias förändras – och vad som får honom att ändra sig.',
 glossary:[{term:'mittgången',explain:'gången mellan sätena i bussen'},{term:'fodral',explain:'ett skyddande hölje, här för en gitarr'},{term:'rodna',explain:'bli röd i ansiktet, ofta av blyghet'}],
 paragraphs:[
  'Varje morgon tar Elias bussen 07.42 från hållplatsen vid tvätteriet. Han sätter sig alltid längst bak, tar på sig hörlurarna och låtsas att han inte ser någon. Det har fungerat i två år.',
  'Men den här tisdagen sitter det redan någon på hans plats. Det är en tjej med grön jacka och en gitarr i ett slitet fodral. Elias stannar i mittgången. Han kan säga något, men han gör det inte. I stället sätter han sig två rader framför henne och höjer volymen.',
  'Vid tredje hållplatsen bromsar bussen hårt. Gitarrfodralet glider ut i gången och slår i hans fot. ”Förlåt!” säger tjejen och rodnar. ”Det är min brors gitarr. Han dödar mig om den går sönder.”',
  'Elias lyfter upp fodralet. Det är tyngre än han trodde. På sidan sitter ett klistermärke från ett band som han själv lyssnar på, ett band som nästan ingen annan i hans klass känner till. Han tar av sig ena hörluren.',
  '”Spelar du själv också?” frågar han. Hon tittar förvånat på honom, som om hon inte väntat sig att han kunde prata. ”Försöker”, säger hon. ”Jag ska spela på skolans konsert på fredag. Jag har typ aldrig varit så nervös.”',
  'Resten av resan pratar de om låtar. När bussen stannar vid skolan märker Elias att han har glömt att sätta på musiken igen. Nästa morgon sätter han sig inte längst bak. Han sätter sig på raden bredvid den gröna jackan.'
 ],
 tasks:[
  {id:'t1',type:'choice',skill:'hitta',ask:'Varför sätter sig Elias inte på sin vanliga plats?',options:['Någon sitter redan där','Bussen är full den dagen','Han vill sitta nära chauffören','Platsen är trasig'],evidence:'Men den här tisdagen sitter det redan någon på hans plats.',why:'Texten säger det rakt ut i andra stycket. Det är en på-raderna-fråga.'},
  {id:'t2',type:'choice',skill:'slutsats',ask:'Vad visar det att Elias höjer volymen när han har satt sig?',options:['Han vill slippa ta kontakt och stänger ute situationen','Han vill visa tjejen att han lyssnar på samma band som hon','Han hör inte musiken eftersom bussen låter mycket när den kör','Han vill att de andra på bussen ska höra vilken låt det är'],evidence:'I stället sätter han sig två rader framför henne och höjer volymen.',why:'Han kunde ha sagt något men gör det inte. Att höja volymen blir ett sätt att slippa situationen. Det står inte rakt ut – du drar slutsatsen.'},
  {id:'t3',type:'evidence',skill:'belägg',claim:'Elias brukar undvika kontakt med andra på bussen.',targets:['tar på sig hörlurarna och låtsas att han inte ser någon'],why:'Att låtsas inte se någon är ett tydligt sätt att undvika kontakt.'},
  {id:'t4',type:'choice',skill:'tolka',ask:'Varför tar Elias av sig ena hörluren?',options:['Klistermärket visar att de gillar samma ovanliga band','Han vill höra vad chauffören säger om den hårda inbromsningen','Tjejen ber honom ta av hörlurarna så att han kan hjälpa henne','Musiken har tagit slut och han behöver inte hörlurarna längre'],evidence:'ett band som nästan ingen annan i hans klass känner till',why:'Bandet är ovanligt, så klistermärket blir något som förenar dem. Det ger honom en anledning att prata.'},
  {id:'t5',type:'choice',skill:'slutsats',ask:'Vad betyder det att Elias ”har glömt att sätta på musiken igen”?',options:['Samtalet var viktigare än att stänga ute omvärlden','Batteriet i hörlurarna tog slut under den långa bussresan','Han ville inte störa de andra passagerarna med sin musik','Han var fortfarande arg på tjejen för att hon tagit platsen'],evidence:'har glömt att sätta på musiken igen',why:'Musiken var hans sätt att stänga ute andra. När han glömmer den har något förändrats.'},
  {id:'t6',type:'order',skill:'struktur',ask:'Tryck på händelserna i den ordning de händer.',items:['Någon sitter på Elias plats','Bussen bromsar och fodralet glider ut','Elias ser klistermärket','De pratar om låtar resten av resan','Elias sätter sig bredvid henne nästa morgon'],why:'En berättelse har ofta en början, en vändpunkt och ett slut. Här är vändpunkten när fodralet glider ut.'},
  {id:'t7',type:'cloze',skill:'ord',sentence:'Hon blev röd i ansiktet och ___ när alla tittade på henne.',accept:['rodnade'],near:{rodnar:'Rätt ord, men meningen står i dåtid. Skriv rodnade.'},options:['rodnade','bromsade','viskade'],why:'Att rodna betyder att bli röd i ansiktet, ofta av blyghet eller skam.'},
  {id:'t8',type:'open',skill:'resonera',ask:'Vad har förändrats för Elias i slutet av texten? Använd minst en detalj ur texten.',criteria:['Säger vad som har förändrats (t.ex. att han vågar ta kontakt eller inte gömmer sig längre)','Stöder svaret med en detalj ur texten (platsen, hörluren eller musiken)','Förklarar med egna ord och inte bara citat'],model:'I början gömmer sig Elias bakom hörlurarna och sätter sig längst bak för att slippa andra. I slutet väljer han själv att sätta sig bredvid tjejen. Att han glömmer musiken visar att han inte längre vill stänga ute omvärlden.'}
 ],
 talk:{prompt:'Har ni varit med om att en liten detalj, som ett klistermärke eller en tröja, startat ett samtal med någon ny?',follow:'Varför kan det vara lättare att prata om en sak än om sig själv?'}
});

T.push({
 id:'datorlan',lang:'sv',version:1,level:1,genre:'Informationstext',
 title:'Regler för lån av skoldator',
 lead:'En avsiktligt torr regeltext. Träna på att hitta det som gäller utan att läsa allt lika noga.',
 purpose:'Läs för att hitta vad som gäller. Du behöver inte komma ihåg allt, men veta var det står.',
 note:'Påhittad skolas regler, skrivna i samma stil som riktiga låneavtal.',
 glossary:[{term:'vårdnadshavare',explain:'förälder eller annan vuxen som har ansvar för dig'},{term:'egendom',explain:'något som någon äger'},{term:'ersättningsskyldig',explain:'tvungen att betala för en skada'}],
 paragraphs:[
  'Alla elever i årskurs 7–9 kan låna en skoldator för arbete hemma. Lånet gäller ett läsår i taget och ska förnyas varje höst. För att få låna måste en vårdnadshavare skriva under låneavtalet. Avtalet lämnas till expeditionen, inte till din mentor.',
  'Datorn är skolans egendom. Du får inte installera egna program, och du får inte ta bort skolans inloggning. Datorn ska laddas hemma varje kväll, eftersom det inte finns laddare i klassrummen. Om batteriet tar slut under lektionen kan du låna en reservdator i biblioteket under högst en dag.',
  'Om datorn går sönder ska du anmäla det till IT-ansvarig inom tre skoldagar. Beskriv vad som hänt så noga som möjligt. Skador som uppstått av olyckshändelse ersätts av skolans försäkring. Om skadan har orsakats med avsikt, eller om datorn har lånats ut till någon annan, kan vårdnadshavaren bli ersättningsskyldig.',
  'Om du byter skola eller slutar årskurs 9 ska datorn, laddaren och väskan lämnas tillbaka senast den sista skoldagen. Tänk på att spara dina egna filer i skolans molntjänst innan du lämnar tillbaka datorn. Datorn återställs innan nästa elev får den, och då raderas allt som finns sparat på den.'
 ],
 tasks:[
  {id:'t1',type:'choice',skill:'hitta',ask:'Var ska låneavtalet lämnas?',options:['På expeditionen','Till mentorn','Hos IT-ansvarig','I biblioteket'],evidence:'Avtalet lämnas till expeditionen, inte till din mentor.',why:'Texten säger både var avtalet ska lämnas och var det inte ska lämnas. Lätt att läsa fel om man skummar för snabbt.'},
  {id:'t2',type:'choice',skill:'hitta',ask:'Vad gäller om batteriet tar slut mitt under en lektion?',options:['Du kan låna en reservdator i biblioteket i högst en dag','Du kan ladda datorn vid lärarens skrivbord i klassrummet','Du får gå hem och ladda den och sedan komma tillbaka','IT-ansvarig lånar ut en ny dator som du får behålla'],evidence:'kan du låna en reservdator i biblioteket under högst en dag',why:'Det finns inga laddare i klassrummen, därför finns reservdatorn.'},
  {id:'t3',type:'choice',skill:'slutsats',ask:'Amir lånade ut sin skoldator till sin kusin, som tappade den. Vad säger reglerna?',options:['Amirs vårdnadshavare kan få betala','Skolans försäkring betalar eftersom det var en olycka','Kusinens föräldrar måste betala för skadan','Amir får en reservdator från biblioteket'],evidence:'om datorn har lånats ut till någon annan, kan vårdnadshavaren bli ersättningsskyldig',why:'Det var en olycka, men datorn var utlånad. Den regeln väger tyngre än regeln om olyckshändelser.'},
  {id:'t4',type:'evidence',skill:'belägg',claim:'Det är viktigt att flytta sina egna filer innan datorn lämnas tillbaka.',targets:['då raderas allt som finns sparat på den'],why:'Skälet till att spara filerna står i sista meningen: allt raderas.'},
  {id:'t5',type:'choice',skill:'syfte',ask:'Vad är huvudsyftet med texten?',options:['Att informera om villkor och ansvar vid datorlån','Att övertyga eleverna om att de borde låna en dator','Att berätta om en elev som förlorade sin skoldator','Att förklara hur man installerar program på datorn'],evidence:'',why:'Texten innehåller regler och villkor, inte åsikter eller en berättelse. Det är en informerande text.'},
  {id:'t6',type:'choice',skill:'strategi',ask:'Du vill snabbt veta vad som gäller om datorn går sönder. Hur läser du smartast?',options:['Letar upp stycket om skador och läser just det noga','Läser hela texten högt två gånger från början till slut','Läser bara första meningen i varje stycke och gissar','Börjar med sista stycket eftersom det viktigaste står sist'],evidence:'Om datorn går sönder ska du anmäla det till IT-ansvarig inom tre skoldagar.',why:'I informationstexter söker man först rätt avsnitt och läser det sedan noga. Det kallas sökläsning.'},
  {id:'t7',type:'cloze',skill:'ord',sentence:'Den som har sönder något med flit kan bli ___ och tvingas betala.',accept:['ersättningsskyldig'],near:{ersättningsskyldiga:'Nästan! Det gäller en person, så ordet ska stå i singular: ersättningsskyldig.'},options:['ersättningsskyldig','försäkrad','återställd'],why:'Ersättningsskyldig betyder att man måste betala för skadan.'},
  {id:'t8',type:'open',skill:'resonera',ask:'Skriv tre korta råd till en kompis som ska låna en dator för första gången.',criteria:['Ett råd handlar om att ladda hemma eller anmäla skador inom tre skoldagar','Ett råd handlar om att inte låna ut datorn eller installera egna program','Råden är korta, tydliga och skrivna med egna ord'],model:'1. Ladda datorn varje kväll – det finns inga laddare i skolan. 2. Låna aldrig ut den, då kan dina föräldrar få betala om något händer. 3. Spara dina filer i molnet innan du lämnar tillbaka den.'}
 ],
 talk:{prompt:'Varför skrivs regler ofta på ett så torrt sätt? Vad skulle hända om reglerna var skrivna som en berättelse?',follow:'Hitta en mening som kan missförstås och skriv om den så att den blir tydligare.'}
});

T.push({
 id:'somn',lang:'sv',version:1,level:2,genre:'Faktatext',
 title:'Varför är tonåringar trötta på morgonen?',
 lead:'Tröttheten beror inte bara på mobilen. En förklarande text om kroppens inre klocka.',
 purpose:'Läs för att kunna förklara för någon annan varför tonåringar ofta är trötta – med fakta från texten.',
 note:'Faktatexten är skriven för övning och förenklar forskningen om sömn.',
 related:'skolstart',
 paragraphs:[
  'Klockan är 06.45 och väckarklockan ringer. Kroppen protesterar, ögonen vill inte öppna sig och den första lektionen känns oändligt avlägsen. Många tonåringar känner igen sig. Men tröttheten beror inte bara på att man har varit uppe för länge med mobilen. En stor del av förklaringen finns i kroppens inre klocka.',
  'Kroppen har en dygnsrytm, ett inre schema som styr när vi känner oss pigga och när vi blir sömniga. En viktig del av systemet är hormonet melatonin, som kroppen börjar producera när det blir mörkt och som gör oss sömniga. Under puberteten förskjuts dygnsrytmen. Melatoninet börjar utsöndras senare på kvällen än hos barn och vuxna. Därför kan en fjortonåring ha svårt att somna klockan tio, även om hon eller han är trött på riktigt.',
  'Samtidigt behöver tonåringar mycket sömn. Sömnforskare brukar rekommendera mellan åtta och tio timmar per natt i åldern 13 till 18 år. Den som somnar vid midnatt och går upp kvart i sju får mindre än sju timmar. Om det upprepas varje vecka byggs ett sömnunderskott upp, och det går inte att sova ikapp helt under helgen.',
  'Sömnbrist märks på flera sätt. Det blir svårare att koncentrera sig och att minnas det man lärt sig, eftersom hjärnan använder sömnen till att bearbeta och spara nya minnen. Humöret påverkas också: den som sover för lite blir ofta mer irriterad och har svårare att hantera stress.',
  'Skärmar spelar också en roll, men kanske inte på det sätt många tror. Ljuset från en skärm kan fördröja melatoninet något. Det som ofta stör mer är innehållet. En spännande serie, ett bråk i gruppchatten eller ett spel som alltid erbjuder en runda till håller hjärnan vaken. Det är alltså inte bara ljuset, utan också engagemanget, som gör att man somnar senare.',
  'Vad kan man göra? Forskare och skolsköterskor brukar ge liknande råd: gå upp ungefär samma tid varje dag, även på helgen, få dagsljus på morgonen och lägg undan mobilen en stund före sänggåendet. Inget av råden är magiskt, men tillsammans kan de göra det lättare att somna. Frågan om skolan borde börja senare är däremot svårare, och den diskuteras fortfarande.'
 ],
 tasks:[
  {id:'t1',type:'choice',skill:'hitta',ask:'Vad händer med dygnsrytmen under puberteten?',options:['Den förskjuts så att man blir sömnig senare på kvällen','Den gör att man blir sömnig tidigare på kvällen än förut','Den försvinner helt under några år och kommer sedan tillbaka','Den börjar styras av skärmljuset i stället för av mörkret'],evidence:'Under puberteten förskjuts dygnsrytmen.',why:'Melatoninet kommer senare på kvällen, därför blir man sömnig senare.'},
  {id:'t2',type:'choice',skill:'slutsats',ask:'En elev somnar 23.30 och går upp 06.30. Hur förhåller sig det till rekommendationen i texten?',options:['Hen sover sju timmar, vilket är under rekommendationen','Hen sover åtta timmar, vilket är precis vad som rekommenderas','Hen sover tio timmar, vilket är mer än vad som rekommenderas','Det går inte att räkna ut eftersom texten inte nämner tider'],evidence:'mellan åtta och tio timmar per natt',why:'Från 23.30 till 06.30 är det sju timmar. Rekommendationen är åtta till tio timmar.'},
  {id:'t3',type:'evidence',skill:'belägg',claim:'Sömn hjälper oss att komma ihåg det vi har lärt oss.',targets:['hjärnan använder sömnen till att bearbeta och spara nya minnen'],why:'Meningen förklarar varför sömnbrist gör det svårare att minnas.'},
  {id:'t4',type:'choice',skill:'tolka',ask:'Vilket påstående stämmer bäst med det texten säger om skärmar?',options:['Både skärmljuset och innehållet kan göra att man somnar senare','Skärmljuset är den viktigaste orsaken till att tonåringar är trötta','Skärmljus påverkar inte sömnen, det är bara innehållet som stör','Skärmar gör att man sover djupare men kortare tid per natt'],evidence:'Det är alltså inte bara ljuset, utan också engagemanget, som gör att man somnar senare.',why:'Texten nämner båda: ljuset ”kan fördröja melatoninet något”, men innehållet stör ofta mer.'},
  {id:'t5',type:'choice',skill:'syfte',ask:'Varför börjar texten med en väckarklocka som ringer 06.45?',options:['För att läsaren ska känna igen sig och bli intresserad','För att bevisa att alla tonåringar sover för lite på vardagar','För att visa vilken tid skolan börjar på de flesta skolor','För att klockslaget är den viktigaste uppgiften i texten'],evidence:'Många tonåringar känner igen sig.',why:'Faktatexter börjar ofta med en vardaglig situation för att fånga läsaren innan förklaringen kommer.'},
  {id:'t6',type:'choice',skill:'kritik',ask:'Vilken mening visar tydligast att texten är försiktig med sina påståenden?',options:['Inget av råden är magiskt, men tillsammans kan de göra det lättare att somna.','Om det upprepas varje vecka byggs ett sömnunderskott upp, och det går inte att sova ikapp helt under helgen.','Kroppen har en dygnsrytm, ett inre schema som styr när vi känner oss pigga och när vi blir sömniga.','Klockan är 06.45 och väckarklockan ringer.'],evidence:'Inget av råden är magiskt',why:'Ord som ”inte magiskt” och ”kan” visar att skribenten inte lovar för mycket. Det är ett tecken på en saklig text.'},
  {id:'t7',type:'choice',skill:'ord',ask:'Vad betyder ”förskjuts” i texten?',options:['Flyttas till en annan tidpunkt','Blir kortare och mer oregelbunden','Försvinner under några år','Delas upp i flera delar'],evidence:'Under puberteten förskjuts dygnsrytmen.',why:'Att något förskjuts betyder att det flyttas. Här flyttas sömnigheten till senare på kvällen.'},
  {id:'t8',type:'cloze',skill:'ord',sentence:'Efter flera korta nätter hade hon ett stort ___ som en sovmorgon på lördagen inte räckte till.',accept:['sömnunderskott'],near:{'sömnbrist':'Nära i betydelse, men meningen säger ”ett stort”. Ordet i texten för det som byggs upp är sömnunderskott.'},options:['sömnunderskott','dygnsrytm','melatonin'],why:'Ett underskott är något som saknas och som har samlats på hög.'},
  {id:'t9',type:'open',skill:'resonera',ask:'Texten säger att frågan om senare skolstart ”diskuteras fortfarande”. Ge ett skäl för och ett skäl emot att skolan börjar senare.',criteria:['Ett skäl för, kopplat till dygnsrytm eller sömnbehov','Ett skäl emot, till exempel senare slut, fritidsaktiviteter eller att man bara lägger sig senare','Skälen förklaras och räknas inte bara upp'],model:'För: tonåringars dygnsrytm är förskjuten, så en senare start skulle ge mer sömn och bättre koncentration. Emot: skoldagen skulle sluta senare, vilket krockar med träningar och jobb, och en del kanske bara skulle lägga sig ännu senare.'}
 ],
 talk:{prompt:'Vilket av råden i sista stycket vore lättast respektive svårast för er att följa? Varför?',follow:'Gör en plan för en vecka: vad provar ni, och hur vet ni om det fungerar?'}
});

T.push({
 id:'simhall',lang:'sv',version:1,level:2,genre:'Nyhetsartikel och källkritik',
 title:'Klippet som fick stan att tro att simhallen stänger',
 lead:'Ett skämt blev en ”nyhet” på ett dygn. Hur gick det till?',
 purpose:'Läs för att förstå hur en falsk uppgift sprids – och hur man kan granska den.',
 note:'Fiktiv nyhetsartikel. Lindvik, personer och citat är påhittade.',
 paragraphs:[
  'I söndags spreds ett kort videoklipp snabbt i flera gruppchattar i Lindvik. I klippet syns en tom simhall med avstängda lampor, och en röst säger: ”Nu är det slut. Från och med i höst stänger Lindviksbadet för gott.” Inom ett dygn hade klippet delats hundratals gånger, och kommunens telefonväxel fick ta emot ovanligt många samtal.',
  'Men uppgiften stämmer inte. ”Lindviksbadet ska inte stänga”, säger Hanna Berg, som är chef för kommunens fritidsförvaltning. ”Badet kommer att vara stängt i tre veckor i oktober för att byta ventilationen. Det har vi informerat om på vår webbplats sedan i våras.”',
  'Hur kunde ett tillfälligt renoveringsstopp bli en nyhet om en nedläggning? Lokaltidningen har följt klippets väg bakåt. Den första versionen lades upp av ett konto som skämtar om händelser i stan. Där fanns ordet ”satir” i profilen, men när klippet sparades och skickades vidare försvann den informationen. I de senare versionerna fanns bara bilden och rösten kvar.',
  'Medieforskaren Jonas Ekholm menar att det här är ett vanligt mönster. ”Ett klipp som väcker starka känslor delas snabbare än ett klipp som är korrekt”, säger han. ”Och när man får något från en kompis litar man på det, eftersom man litar på kompisen. Men kompisen har kanske inte heller kontrollerat något.”',
  'Ekholm ger tre råd. Det första är att leta efter ursprunget: vem lade upp klippet från början, och varför? Det andra är att kontrollera uppgiften hos någon som borde veta, till exempel kommunen eller en etablerad nyhetsredaktion. Det tredje är att vänta lite innan man delar. ”Om något är sant är det fortfarande sant om en timme”, säger han.',
  'Kontot som skapade klippet har nu lagt upp ett nytt inlägg där det står att klippet var ett skämt. Det inlägget har hittills delats elva gånger.'
 ],
 tasks:[
  {id:'t1',type:'choice',skill:'hitta',ask:'Varför ska Lindviksbadet vara stängt i oktober?',options:['Ventilationen ska bytas','Badet ska läggas ner för gott','Kommunen har inte råd att hålla öppet','Det har blivit för få besökare'],evidence:'Badet kommer att vara stängt i tre veckor i oktober för att byta ventilationen.',why:'Det rör sig om ett tillfälligt stopp, inte en nedläggning.'},
  {id:'t2',type:'choice',skill:'slutsats',ask:'Varför trodde många att klippet var sant?',options:['Ordet satir försvann när klippet skickades vidare','Kommunen hade själv lagt upp klippet på sin webbplats','Klippet visade ett officiellt beslut från kommunen','Lokaltidningen var först med att publicera klippet'],evidence:'när klippet sparades och skickades vidare försvann den informationen',why:'Utan ordet ”satir” fanns inget som visade att det var ett skämt.'},
  {id:'t3',type:'evidence',skill:'belägg',claim:'Människor litar på information som kommer från någon de känner.',targets:['när man får något från en kompis litar man på det'],why:'Ekholm förklarar att förtroendet för kompisen smittar av sig på klippet.'},
  {id:'t4',type:'order',skill:'struktur',ask:'Tryck på händelserna i den ordning de hände.',items:['Ett skämtkonto lägger upp klippet','Klippet sprids utan ordet satir','Kommunens växel får många samtal','Kontot skriver att klippet var ett skämt'],why:'Artikeln börjar mitt i händelsen och berättar sedan bakåt. Därför måste du sortera själv.'},
  {id:'t5',type:'choice',skill:'tolka',ask:'Vad vill journalisten troligen visa med sista meningen, om att rättelsen har delats elva gånger?',options:['Att rättelser sprids mycket långsammare än falska nyheter','Att kontot som gjorde klippet nästan inte har några följare','Att invånarna i Lindvik inte bryr sig om simhallen längre','Att rättelsen inte stämmer och att klippet egentligen var sant'],evidence:'Det inlägget har hittills delats elva gånger.',why:'Jämför med ”hundratals gånger” i första stycket. Kontrasten säger något utan att journalisten skriver det rakt ut.'},
  {id:'t6',type:'choice',skill:'kritik',ask:'Du får ett klipp om att skolan har lov på fredag. Vilket av Ekholms råd hjälper dig bäst att ta reda på om det stämmer?',options:['Kontrollera uppgiften hos skolan, som borde veta','Se efter om klippet har många visningar och delningar','Se efter om klippet ser professionellt och trovärdigt ut','Dela det i klassens chatt och se vad de andra säger'],evidence:'kontrollera uppgiften hos någon som borde veta',why:'Antal visningar och hur proffsigt något ser ut säger ingenting om ifall det är sant.'},
  {id:'t7',type:'cloze',skill:'ord',sentence:'Programmet var ___, alltså ett skämt som skulle få oss att tänka, inte en riktig nyhet.',accept:['satir','en satir'],near:{satiriskt:'Nästan! Meningen behöver substantivet: satir.'},options:['satir','renovering','ursprung'],why:'Satir är humor som driver med något verkligt för att kritisera eller väcka tankar.'},
  {id:'t8',type:'open',skill:'resonera',ask:'Vem har mest ansvar för att det falska klippet spreds: skämtkontot, de som delade det eller plattformen? Motivera med stöd i texten.',criteria:['Tar ställning för en eller flera parter','Använder minst en uppgift ur texten som stöd','Visar att ansvaret kan delas, eller bemöter ett motargument'],model:'Skämtkontot märkte klippet som satir, så det största ansvaret ligger hos dem som delade det utan att kontrollera. Men kontot kunde ha skrivit ”skämt” i själva klippet, eftersom det var lätt att förutse att profiltexten skulle försvinna.'}
 ],
 talk:{prompt:'Har ni själva delat eller trott på något som visade sig vara fel? Vad fick det att verka trovärdigt?',follow:'Skriv en regel för er gruppchatt om hur man delar nyheter.'}
});

T.push({
 id:'skolstart',lang:'sv',version:1,level:3,genre:'Debattartikel',
 title:'Låt skoldagen börja klockan nio',
 lead:'En elev i årskurs 9 argumenterar för senare skolstart. Hur bra är argumenten egentligen?',
 purpose:'Läs för att hitta tesen, argumenten och hur skribenten bemöter kritik. Granska sedan om argumenten håller.',
 note:'Påhittad debattartikel. Bygger delvis på samma fakta som faktatexten om tonåringars sömn.',
 related:'somn',
 paragraphs:[
  'Varje morgon sitter tusentals elever i svenska klassrum och kämpar för att hålla ögonen öppna. Lärare vet det, föräldrar vet det och eleverna själva vet det bäst av alla. Ändå börjar många högstadieskolor fortfarande klockan åtta, eller till och med tidigare. Jag anser att det är dags att ändra på det. Skoldagen för elever i årskurs 7–9 bör börja tidigast klockan nio.',
  'Mitt första argument handlar om biologi. Under tonåren förskjuts kroppens dygnsrytm, och hormonet melatonin, som gör oss sömniga, börjar utsöndras senare på kvällen. En tonåring som går och lägger sig klockan tio ligger alltså ofta vaken länge. Att kräva att samma person ska vara pigg och lärbenägen klockan åtta är som att kräva att en vuxen ska lösa ekvationer klockan sex på morgonen. Det går, men det är inte när hjärnan fungerar bäst.',
  'Mitt andra argument är att sömn påverkar lärandet. Hjärnan använder sömnen till att spara det vi har lärt oss under dagen. Elever som sover för lite får svårare att koncentrera sig, minnas och hantera stress. Om skolan menar allvar med att alla elever ska nå sin fulla potential borde den också ta hänsyn till när eleverna faktiskt kan lära sig.',
  'Mitt tredje argument är att försök redan har gjorts. Flera skolor i olika länder har flyttat skolstarten senare, och i en del av dessa försök har eleverna sovit längre och kommit i tid oftare. Resultaten är inte entydiga överallt, men de visar att förändringen är möjlig att genomföra.',
  'Kritiker brukar invända att eleverna bara kommer att lägga sig ännu senare om skolan börjar senare. Det är en rimlig farhåga, men den stämmer inte helt. Eftersom dygnsrytmen styrs av kroppen och inte bara av vanor, kan man inte förvänta sig att läggdags flyttas lika mycket som skolstarten. En annan invändning är att skoldagen då slutar senare och krockar med träningar och fritidsaktiviteter. Det problemet är verkligt, men det handlar om att planera om, inte om att tonåringars hälsa är mindre viktig än en fotbollsträning klockan fem.',
  'Det finns också de som menar att skolan ska förbereda unga för arbetslivet, där man ofta börjar tidigt. Men skolan är inte ett arbete, och en fjortonårings kropp är inte en vuxens. Vi anpassar redan undervisningen efter elevernas ålder på många andra sätt. Varför skulle just tiden vara omöjlig att ändra?',
  'Jag föreslår därför att kommunerna gör ett försök under ett läsår, där några högstadieskolor börjar klockan nio. Låt elever, lärare och föräldrar utvärdera resultatet. Om det inte fungerar kan vi gå tillbaka. Om det fungerar har vi gett tusentals unga en bättre chans att lära sig – och det borde vara skolans viktigaste uppdrag.',
  'Alva Lindqvist, elev i årskurs 9'
 ],
 tasks:[
  {id:'t1',type:'choice',skill:'hitta',ask:'Vilken är skribentens tes?',options:['Skoldagen för årskurs 7–9 bör börja tidigast klockan nio','Elever i årskurs 7–9 borde sova längre på helgerna','Melatonin gör att tonåringar blir sömniga senare på kvällen','Kommunerna borde låta eleverna bestämma sitt eget schema'],evidence:'Skoldagen för elever i årskurs 7–9 bör börja tidigast klockan nio.',why:'Tesen är det skribenten vill övertyga om. Den står ofta i början, här efter ”Jag anser”.'},
  {id:'t2',type:'order',skill:'struktur',ask:'Tryck på artikelns delar i den ordning de kommer.',items:['Tes: skolan bör börja senare','Argument om biologi och dygnsrytm','Argument om sömn och lärande','Bemötande av motargument','Förslag om ett försök under ett läsår'],why:'En debattartikel bygger ofta på tes – argument – motargument och bemötande – avslutning med förslag.'},
  {id:'t3',type:'choice',skill:'kritik',ask:'Vilket motargument bemöter skribenten först i stycke 5?',options:['Att eleverna bara skulle lägga sig senare','Att lärarna inte vill börja senare','Att det kostar för mycket pengar','Att föräldrar vill att barnen ska vara hemma'],evidence:'eleverna bara kommer att lägga sig ännu senare',why:'Skribenten kallar det en ”rimlig farhåga” och försöker sedan visa varför den inte stämmer helt.'},
  {id:'t4',type:'choice',skill:'tolka',ask:'Skribenten jämför en tonåring klockan åtta med en vuxen som löser ekvationer klockan sex. Vad är syftet med jämförelsen?',options:['Att läsaren ska förstå hur det känns genom en bild hen känner igen','Att bevisa vetenskapligt att hjärnan fungerar sämre på morgonen','Att visa att vuxna har svårare för matematik än tonåringar','Att skämta om lärare som vill börja skoldagen tidigt'],evidence:'som att kräva att en vuxen ska lösa ekvationer klockan sex på morgonen',why:'En jämförelse bevisar inget, men den får läsaren att känna igen sig. Det är ett retoriskt grepp.'},
  {id:'t5',type:'evidence',skill:'belägg',claim:'Skribenten medger att forskningen inte ger samma svar överallt.',targets:['Resultaten är inte entydiga överallt'],why:'Att medge en svaghet kan göra en skribent mer trovärdig.'},
  {id:'t11',type:'choice',skill:'slutsats',ask:'Vad kan man sluta sig till om hur Alva värderar fritidsaktiviteter, utifrån stycke 5?',options:['Hon tycker att elevernas hälsa väger tyngre än tiderna för träningar','Hon vill att alla fritidsaktiviteter på kvällen ska läggas ner','Hon tycker att fotbollsträning är viktigare än skolan','Hon menar att träningar borde flyttas till tidigt på morgonen'],evidence:'inte om att tonåringars hälsa är mindre viktig än en fotbollsträning klockan fem',why:'Hon säger inte rakt ut vad hon tycker om träningar, men hon jämför dem med elevernas hälsa och låter hälsan väga tyngst.'},
  {id:'t6',type:'choice',skill:'kritik',ask:'Vilken är den största svagheten i skribentens tredje argument?',options:['Det nämns inga konkreta skolor, länder eller siffror','Argumentet säger emot den tes som skribenten har','Argumentet är för långt och tar upp för många saker','Argumentet bygger bara på skribentens egna känslor'],evidence:'Flera skolor i olika länder har flyttat skolstarten senare',why:'Utan exempel eller källor kan läsaren inte kontrollera påståendet. Ett starkare argument hade namngett en studie eller en skola.'},
  {id:'t7',type:'choice',skill:'ord',ask:'Vad betyder ”farhåga” i texten?',options:['En oro för att något dåligt ska hända','Ett bevis för att något stämmer','En förhoppning om att något ska bli bättre','Ett skämt som kritikerna brukar säga'],evidence:'Det är en rimlig farhåga',why:'Farhåga hör ihop med fara: en rädsla för att något negativt ska inträffa.'},
  {id:'t8',type:'cloze',skill:'ord',sentence:'Resultaten var inte ___; vissa skolor såg förbättringar och andra inga alls.',accept:['entydiga'],near:{tydliga:'Nära i betydelse, men texten använder ordet entydiga: att resultaten pekar åt samma håll.',entydigt:'Nästan! Ordet ska böjas efter ”resultaten” (plural): entydiga.'},options:['entydiga','rimliga','biologiska'],why:'Entydig betyder att något bara kan tolkas på ett sätt.'},
  {id:'t9',type:'open',skill:'resonera',ask:'Jämför debattartikeln med faktatexten om tonåringars sömn. Vad gör skribenten med samma fakta som faktatexten inte gör?',criteria:['Ser att båda texterna bygger på samma fakta om dygnsrytm och melatonin','Förklarar att debattartikeln använder fakta för att övertyga och driva ett förslag','Nämner minst ett retoriskt grepp, till exempel jämförelse, retorisk fråga eller ”jag anser”'],model:'Båda texterna tar upp att dygnsrytmen förskjuts och att sömn påverkar minnet. Faktatexten förklarar och är försiktig, och lämnar frågan om skolstart öppen. Debattartikeln använder samma fakta som argument för en tydlig tes, och lägger till jämförelser och en retorisk fråga för att övertyga.'},
  {id:'t10',type:'open',skill:'resonera',ask:'Skriv ett kort svar till Alva där du bemöter ett av hennes argument.',criteria:['Säger vilket argument som bemöts','Ger ett eget motargument med ett skäl','Tonen är saklig och respektfull'],model:'Alva, du skriver att försök redan har gjorts, men du nämner inte en enda skola eller siffra. Innan kommunerna ändrar schemat för tusentals elever behöver vi veta vad som faktiskt hände i de försöken.'}
 ],
 talk:{prompt:'Debattera i två minuter var: en är för och en är emot senare skolstart. Byt sedan sida.',follow:'Vilket argument var svårast att bemöta? Varför?'}
});

T.push({
 id:'osagt',lang:'sv',version:1,level:3,genre:'Berättelse',
 title:'Det som inte sades',
 lead:'Saga är säker på att hennes bästa vän tänker lämna deras duo. Men hon ser bara halva berättelsen.',
 purpose:'Läs som en detektiv. Saga missförstår ledtrådar som du kanske ser. Leta efter dem.',
 paragraphs:[
  'Nour och jag hade spelat tillsammans i två år. Hon sjöng, jag spelade gitarr, och vi hade bestämt oss för att vinna skolans talangtävling i november. Vi hade till och med ett namn: Andra Versen. Det var Nours idé. ”Ingen minns första versen”, hade hon sagt. ”Det är i andra versen låten blir på riktigt.”',
  'Men i oktober började något förändras. Nour ställde in två repetitioner i rad. Första gången skrev hon att hon var sjuk. Andra gången skrev hon bara: ”Kan inte idag, sorry.” Ingen förklaring, inget hjärta, inte ens en emoji. När jag frågade i skolan vad som hänt ryckte hon på axlarna och sa: ”Det är inget.”',
  'Samma vecka såg jag henne i matsalen med Ella och hennes kompisar. Ella spelar keyboard i ett band som alltid vinner allt. De satt tätt ihop och tittade på något i Ellas mobil, och Nour skrattade på ett sätt hon inte hade gjort med mig på flera veckor. Jag satte mig vid ett annat bord. Det var ju uppenbart vad som höll på att hända.',
  'På fredagen kom Nour ändå till repetitionen. Hon var tyst och sjöng som om hon tänkte på något annat. Mitt i refrängen slutade hon. ”Saga, hur lång tid tar det med tåg till Umeå?” frågade hon. Jag förstod inte frågan. ”Ingen aning. Varför?” Hon skakade på huvudet. ”Bara undrar.” Sedan sjöng hon vidare, en halv ton för lågt.',
  'När jag gick hem den kvällen passerade jag hennes hus. Hennes mammas bil stod på uppfarten med bakluckan öppen, full av flyttkartonger. Jag tänkte att de kanske skulle rensa i förrådet. Jag tänkte inte mer på det. Jag tänkte bara på Ella och hennes band.',
  'Dagen före tävlingen gav Nour mig sin kapodaster, den gröna som hon alltid hade i jackfickan fast hon inte spelar gitarr. Hon hade fått den av sin morfar. ”Du kan ha den”, sa hon. ”Den passar dig bättre än mig.” Jag tog emot den utan att säga tack. I mitt huvud var det bara ett sätt att göra det enklare för sig själv när hon skulle berätta att hon tänkte byta band.',
  'På tävlingen spelade jag hårdare än någonsin. Jag ville att alla skulle höra att jag inte behövde henne. Nour tittade på mig flera gånger, som om hon ville säga något, men jag tittade bort. Vi kom trea. Ellas band vann, som vanligt.',
  'Efteråt, i korridoren bakom aulan, sa Nour det till slut. Hennes mamma hade fått ett jobb i Umeå. De skulle flytta i december. Hon hade vetat det sedan september men inte vetat hur hon skulle säga det. ”Jag ville inte att det skulle bli det enda vi pratade om”, sa hon. ”Ella flyttade hit från Umeå. Jag frågade henne hur det är där.”',
  'Jag stod kvar länge efter att hon hade gått. Jag hade sett allt: de inställda repetitionerna, frågan om tåget, bilen full av kartonger. Jag hade bara satt ihop det till fel berättelse, den där jag var den som blev lämnad. Jag höll kapodastern så hårt att den lämnade märken i handflatan. Den passar dig bättre än mig, hade hon sagt. Det var hennes sätt att säga hejdå, och jag hade inte ens sagt tack.'
 ],
 glossary:[{term:'kapodaster',explain:'en klämma man sätter på gitarrens hals för att höja tonarten'}],
 tasks:[
  {id:'t1',type:'choice',skill:'hitta',ask:'Varför valde Nour namnet Andra Versen?',options:['För att låten blir på riktigt i andra versen','För att de var två personer som spelade i duon','För att de hade kommit tvåa i tävlingen förra året','För att alla brukar minnas första versen bäst'],evidence:'Det är i andra versen låten blir på riktigt.',why:'Hennes förklaring står direkt efter namnet. Lägg märke till att ett av alternativen säger motsatsen: att första versen är den man minns.'},
  {id:'t2',type:'choice',skill:'slutsats',ask:'Hur tolkar Saga det hon ser i matsalen?',options:['Att Nour tänker lämna duon för Ellas band','Att Nour och Ella planerar en överraskning för henne','Att Nour är sjuk','Att Ella vill gå med i duon'],evidence:'Det var ju uppenbart vad som höll på att hända.',why:'Saga skriver aldrig ut sin tolkning i matsalen, men senare säger hon att hon trodde att Nour ”tänkte byta band”.'},
  {id:'t3',type:'evidence',skill:'belägg',claim:'Det fanns en tydlig ledtråd om att Nours familj skulle flytta, men Saga tog den inte på allvar.',targets:['full av flyttkartonger','Jag tänkte att de kanske skulle rensa i förrådet.'],why:'Saga ser kartongerna men förklarar bort dem. Det är typiskt för en berättare som redan bestämt sig.'},
  {id:'t4',type:'choice',skill:'slutsats',ask:'Varför frågar Nour hur lång tid det tar med tåg till Umeå?',options:['Hon tänker på flytten och försöker närma sig ämnet','Hon ska åka på semester dit med sin familj i jul','Ella har bjudit henne till en konsert i Umeå','Hon vill byta ämne för att slippa prata om musiken'],evidence:'hur lång tid tar det med tåg till Umeå',why:'I slutet får vi veta att familjen flyttar till Umeå. I efterhand blir frågan ett försök att börja prata om det.'},
  {id:'t5',type:'choice',skill:'tolka',ask:'Vad betyder kapodastern för Nour, utifrån slutet?',options:['Ett minne från morfar som hon ger bort som ett avsked','Ett tecken på att hon ska sluta sjunga och börja spela gitarr','En ursäkt för att hon har ställt in repetitionerna','Något hon inte behöver eftersom hon inte spelar gitarr'],evidence:'Det var hennes sätt att säga hejdå',why:'Den kommer från morfar och hon har den alltid med sig. Att ge bort den är stort – det blir hennes avsked.'},
  {id:'t6',type:'choice',skill:'tolka',ask:'Texten berättas av Saga i jagform. Vilken effekt får det?',options:['Läsaren ser ledtrådarna, men också hur Saga missförstår dem','Läsaren får veta allt som Nour tänker och känner under hösten','Berättelsen blir helt objektiv eftersom Saga bara beskriver','Läsaren får veta hur berättelsen slutar redan i början'],evidence:'Jag hade bara satt ihop det till fel berättelse',why:'Vi ser världen genom Sagas ögon. Därför kan vi själva upptäcka det hon missar.'},
  {id:'t7',type:'order',skill:'struktur',ask:'Tryck på händelserna i den ordning de händer.',items:['Nour ställer in två repetitioner','Saga ser Nour med Ella i matsalen','Saga ser flyttkartongerna','Nour ger bort kapodastern','Nour berättar om flytten'],why:'Ledtrådarna kommer en i taget. Förklaringen kommer först i slutet.'},
  {id:'t8',type:'cloze',skill:'ord',sentence:'Det var ___ för alla utom honom att laget skulle förlora.',accept:['uppenbart','tydligt','självklart'],near:{uppenbar:'Nästan! Ordet ska stå i neutrum efter ”det var”: uppenbart.'},options:['uppenbart','tillfälligt','ovanligt'],why:'Saga använder ordet uppenbart i matsalen. Tydligt och självklart betyder nästan samma sak och godtas.'},
  {id:'t9',type:'open',skill:'resonera',ask:'Titeln är ”Det som inte sades”. Förklara titeln med stöd i texten. Vad sägs inte, och av vem?',criteria:['Nämner att Nour inte berättar om flytten','Nämner något Saga inte säger, till exempel sin misstanke eller tack','Kopplar till minst en konkret detalj i texten'],model:'Nour säger inte att hon ska flytta, eftersom hon inte vet hur. Saga säger inte heller vad hon misstänker, utan spelar argt och tittar bort. Till slut är det Saga som inte har sagt det enda hon borde ha sagt: tack.'},
  {id:'t10',type:'open',skill:'resonera',ask:'Berätta en scen ur Nours perspektiv, till exempel repetitionen på fredagen. Vad tänker hon?',criteria:['Berättar i jagform som Nour','Använder det Nour vet men Saga inte vet: flytten','Stämmer med det som händer i texten'],model:'Jag vill säga det nu. Hon har rätt att veta. Men om jag säger Umeå blir det sista vi gör tillsammans att vara ledsna. Så jag frågar bara om tåget, som om det inte spelade någon roll, och sjunger vidare.'}
 ],
 talk:{prompt:'Var det rimligt av Saga att misstänka Nour? Vad hade ni själva tänkt?',follow:'Vad hade kunnat bryta missförståndet tidigare – och vem hade ansvaret?'}
});

T.push({"lang":"sv","id":"foreningsbrev","version":1,"level":1,"genre":"Informationsbrev","title":"När träningen flyttar","lead":"Ett informationsbrev från en idrottsförening. Vem ska göra vad och när?","purpose":"Leta fram rätt information och förklara reglerna för en kompis.","glossary":[{"term":"tillfällig","explain":"något som bara gäller under en kort tid"},{"term":"anmälan","explain":"meddelande att man vill vara med"},{"term":"bekräftelse","explain":"svar som visar att något är mottaget"}],"paragraphs":["På måndag morgon sitter ett nytt brev på anslagstavlan i Kvarnvikens idrottshall. Tränaren Mira har skickat samma brev till alla familjer i föreningen. Hon skriver att den stora hallen ska målas om och därför är stängd i två veckor. Ingen träning ställs in helt, men tiderna och platserna blir tillfälligt annorlunda. Mira ber alla läsa hela meddelandet innan de ställer frågor.","Grupp A, som brukar träna på tisdagar, ska i stället komma till den lilla gymnastiksalen vid skolan. Träningen börjar klockan 17.30, en halvtimme tidigare än vanligt. Grupp B fortsätter på torsdagar, men flyttar till fotbollsplanen bakom biblioteket. Vid kraftigt regn får grupp B ett meddelande senast klockan 15 samma dag. Då hålls ett kort träningspass inomhus i skolans matsal.","Alla deltagare ska ta med en vattenflaska och skor som passar platsen. Den som inte kan komma ska meddela tränaren senast dagen före. Man behöver inte anmäla sig på nytt till gruppen. Om en elev vill byta från grupp A till grupp B krävs däremot ett ja från tränaren, eftersom grupperna inte får bli för stora. Mira skriver också att en förälder gärna får hjälpa till att bära material den första tisdagen.","På fredagen får Amir ett sms av sin kompis Leila: 'Ska vi träna som vanligt på tisdag?' Amir svarar först ja, men läser sedan brevet en gång till. Han upptäcker att de måste gå till skolans lilla sal och komma tidigare. Han skickar en ny förklaring till Leila och tar en bild av tid och plats. När nästa vecka börjar kommer båda i rätt tid, med vattenflaskor och inneskor."],"tasks":[{"id":"t1","type":"choice","skill":"hitta","ask":"Var ska grupp A träna under ommålningen?","options":["I den lilla gymnastiksalen vid skolan","På fotbollsplanen bakom biblioteket","I den stora idrottshallen","I skolans matsal när det regnar på torsdagarna"],"evidence":"ska i stället komma till den lilla gymnastiksalen vid skolan","why":"Brevet berättar vilken plats som gäller för grupp A. Leta efter gruppnamnet först."},{"id":"t2","type":"choice","skill":"slutsats","ask":"Varför behöver Amir skicka ett nytt meddelande till Leila?","options":["Han upptäcker att deras vanliga tid och plats har ändrats","Han vill sluta träna i föreningen","Leila har bytt till grupp B utan att fråga","Tränaren har ställt in alla tisdagsträningar under två veckor"],"evidence":"Han upptäcker att de måste gå till skolans lilla sal och komma tidigare.","why":"Amir svarade först utan att kontrollera detaljerna. Efter att ha läst brevet igen rättar han sig."},{"id":"t3","type":"evidence","skill":"belägg","claim":"Det går inte att byta träningsgrupp utan tillstånd.","targets":["krävs däremot ett ja från tränaren"],"why":"Texten skiljer på att fortsätta i samma grupp och att byta till en annan grupp."},{"id":"t4","type":"choice","skill":"tolka","ask":"Vad betyder 'tillfälligt' i brevet?","options":["Att ändringen bara gäller en begränsad tid","Att föreningen aldrig öppnar hallen igen efter ommålningen","Att alla måste byta idrott","Att träningen alltid börjar tidigare"],"evidence":"tiderna och platserna blir tillfälligt annorlunda","why":"Hallen ska målas om i två veckor. Det visar att de nya tiderna inte gäller för alltid."},{"id":"t5","type":"choice","skill":"syfte","ask":"Vad är brevets viktigaste uppgift?","options":["Att berätta hur träningen fungerar medan hallen målas","Att övertyga alla elever om att börja med fotboll nästa termin","Att berätta en rolig historia om tränaren","Att sälja nya träningsskor till föreningen"],"evidence":"","why":"Det är ett informationsbrev med datum, platser och regler. Det försöker hjälpa deltagarna att göra rätt."},{"id":"t6","type":"order","skill":"struktur","ask":"Tryck på händelserna i rätt ordning.","items":["Tränaren skickar ut brevet","Amir svarar Leila för snabbt","Amir läser brevet igen och hittar ändringen","Amir och Leila kommer till rätt sal"],"why":"Ordningen visar hur ett missförstånd kan lösas genom att läsa källan noga."},{"id":"t7","type":"cloze","skill":"ord","sentence":"Ändringen gäller bara nästa vecka och är därför ___.","accept":["tillfällig"],"near":{"tillfälligt":"Tänk på att ordet beskriver en ändring: en tillfällig ändring."},"options":["tillfällig","permanent","försenad"],"why":"Tillfällig betyder att något inte ska fortsätta för alltid."},{"id":"t8","type":"open","skill":"resonera","ask":"Skriv ett kort sms till en elev i grupp A med två viktiga saker från brevet.","criteria":["Skriver rätt plats: skolans lilla gymnastiksal","Skriver rätt tid: tisdag klockan 17.30","Skriver kort och tydligt med egna ord"],"model":"Hej! På tisdag tränar grupp A i lilla gymnastiksalen vid skolan. Vi börjar 17.30, alltså tidigare än vanligt. Ta med vattenflaska och inneskor!"}],"talk":{"prompt":"Varför är det smart att kontrollera ett informationsbrev innan man svarar en kompis?","follow":"Vilka två detaljer skulle du själv markera med penna?"}});
T.push({"lang":"sv","id":"biblioteksintervju","version":1,"level":2,"genre":"Intervju","title":"Vem bestämmer vilka böcker som köps?","lead":"En intervju där en elev ställer frågor om skolbibliotekets val och begränsningar.","purpose":"Skilj mellan intervjuarens frågor, svarspersonens åsikter och sådant som kan kontrolleras.","glossary":[{"term":"urval","explain":"vilka alternativ man väljer bland många"},{"term":"budget","explain":"pengar som finns tillgängliga"},{"term":"önskemål","explain":"det någon skulle vilja ha"}],"paragraphs":["Skolbiblioteket på Norrdalsskolan har fått tre nya bokhyllor, men flera elever undrar varför deras favoritserier fortfarande saknas. Niondeklassaren Ellen bestämmer sig för att intervjua bibliotekarien Samira till skoltidningen. Hon förbereder frågor och börjar med att läsa skolans senaste inköpslista. Där ser hon både romaner, faktaböcker och några böcker på andra språk.","'Är det du som bestämmer allt?' frågar Ellen. Samira skrattar och svarar att hon ansvarar för ett första urval, men att pengarna är begränsade och att skolan har en gemensam budget. Varje termin kan eleverna lämna önskemål i en låda vid entrén. Lärarna berättar också vilka ämnen klasserna ska arbeta med. Bibliotekarien försöker väga samman önskemålen med behovet av böcker för olika läsnivåer.","Ellen frågar varför en populär bokserie bara finns i två exemplar trots att många vill låna den. 'Det handlar inte om att vi ogillar serien', svarar Samira. 'Om vi köper tio exemplar av samma bok räcker pengarna kanske inte till böcker om historia, naturvetenskap och andra berättelser. Ibland beställer vi ett exemplar först och ser hur ofta det lånas.' Ellen påpekar att långa väntetider kan få elever att sluta läsa. Samira håller med om att det är ett problem och föreslår att eleverna också testar liknande serier medan de väntar.","Sedan visar Samira ett diagram över utlåningen. En serie som många önskade förra året lånas nästan aldrig längre. Samtidigt har böcker om rymden blivit mycket populära efter ett skolprojekt. Ellen frågar om det betyder att biblioteket bara följer trender. Samira svarar nej: vissa klassiker köps in även om de inte är populärast just nu. Målet är att elever med olika intressen och läsvanor ska hitta något som passar.","I slutet av intervjun frågar Ellen vad eleverna kan göra för att påverka besluten. Samira svarar att ett konkret önskemål hjälper mer än att bara skriva 'fler bra böcker'. Titel, författare och ett kort skäl gör det lättare att förstå behovet. Ellen bestämmer sig för att publicera både bibliotekariens förklaring och elevernas kritik. Hon tänker att en bra artikel behöver visa varför människor tycker olika, inte bara vem som har sista ordet."],"tasks":[{"id":"t1","type":"choice","skill":"hitta","ask":"Hur kan elever föreslå nya böcker?","options":["Genom att lämna önskemål i en låda vid entrén","Genom att köpa böcker själva åt biblioteket","Genom att skriva önskemålen på klassens anslagstavla efter varje lektion","Genom att skriva på skolans idrottssida"],"evidence":"Varje termin kan eleverna lämna önskemål i en låda vid entrén.","why":"Intervjun säger uttryckligen hur eleverna lämnar förslag på nya böcker."},{"id":"t2","type":"choice","skill":"slutsats","ask":"Varför beställer biblioteket ibland bara ett exemplar först?","options":["För att se om boken verkligen används innan fler köps","För att elever aldrig får läsa samma bok samtidigt","För att författaren inte tillåter flera exemplar","För att se om eleverna faktiskt läser böcker de redan har hemma"],"evidence":"Ibland beställer vi ett exemplar först och ser hur ofta det lånas.","why":"Bibliotekarien vill använda en begränsad budget på böcker som faktiskt behövs."},{"id":"t3","type":"evidence","skill":"belägg","claim":"Biblioteket köper inte bara böcker som är populära just nu.","targets":["vissa klassiker köps in även om de inte är populärast just nu"],"why":"Den meningen visar tydligt att biblioteket också gör långsiktiga val."},{"id":"t4","type":"choice","skill":"kritik","ask":"Vilken invändning kommer från Ellen under intervjun?","options":["Att väntetiden kan göra att elever ger upp läsningen","Att biblioteket inte tar in några nya böcker från lokala författare","Att alla böcker ska ersättas av ljudböcker","Att skoltidningen inte borde skriva om böcker"],"evidence":"långa väntetider kan få elever att sluta läsa","why":"Ellen visar en konsekvens av få exemplar. Det är kritik som bibliotekarien tar på allvar."},{"id":"t5","type":"choice","skill":"syfte","ask":"Varför är texten skriven som en intervju?","options":["För att visa frågor, olika argument och svar direkt","För att dölja vem som står bakom besluten","För att berätta en påhittad deckarhistoria","För att göra reklam för en enda bokserie"],"evidence":"","why":"En intervju låter läsaren höra svarspersonen och se vilka följdfrågor som ställs."},{"id":"t6","type":"order","skill":"struktur","ask":"Tryck på intervjuns delar i rätt ordning.","items":["Ellen studerar inköpslistan","Samira förklarar hur önskemål och budget fungerar","De diskuterar väntetider och olika boktyper","Ellen vill skriva en artikel med båda perspektiven"],"why":"Intervjun går från förberedelse via fakta och kritik till en avslutande slutsats."},{"id":"t7","type":"cloze","skill":"ord","sentence":"Skolan måste planera sina pengar, därför gör den en ___ för året.","accept":["budget"],"near":{"budgeten":"Nära. Men här står 'en', så substantivet ska vara i grundform: budget."},"options":["budget","intervju","novell"],"why":"En budget visar vilka pengar som finns och hur de ska användas."},{"id":"t8","type":"open","skill":"resonera","ask":"Ge ett argument för att köpa fler exemplar av en populär serie och ett argument emot.","criteria":["Förklarar varför fler exemplar kan minska väntetiden","Förklarar varför pengarna också behövs till andra böcker","Använder en konkret detalj ur intervjun"],"model":"Fler exemplar kan göra att elever slipper vänta så länge och fortsätter läsa. Samtidigt finns bara en viss budget, så om biblioteket köper tio av samma serie kanske det inte finns pengar till andra ämnen och intressen."},{"id":"t9","type":"choice","skill":"tolka","ask":"Vad betyder 'urval' här?","options":["De böcker biblioteket väljer bland många möjliga böcker","De elever som får vara med och bestämma vilka böcker som köps","Den tid en bok får vara utlånad","Det antal hyllor som byggs i biblioteket"],"evidence":"hon ansvarar för ett första urval","why":"Urval handlar om att välja mellan alternativ, inte om att bestämma vem som får komma in."}],"talk":{"prompt":"Borde ett skolbibliotek köpa det som flest önskar, eller se till att alla hittar något?","follow":"Vad skulle du fråga bibliotekarien för att förstå beslutet ännu bättre?"}});
